import re,zlib
d=open("/Users/REDACTED_USER/Downloads/Job Management Dashboard.pdf","rb").read()
streams=[]
for m in re.finditer(rb"stream\r?\n(.*?)\r?\nendstream",d,re.S):
    try: streams.append(zlib.decompress(m.group(1)))
    except Exception: pass
cm={}
for s in streams:
    if b"beginbfchar" not in s and b"beginbfrange" not in s: continue
    for blk in re.findall(rb"beginbfchar(.*?)endbfchar",s,re.S):
        for a,b in re.findall(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>",blk):
            cm.setdefault(int(a,16),bytes.fromhex(b.decode()).decode("utf-16-be"))
    for blk in re.findall(rb"beginbfrange(.*?)endbfrange",s,re.S):
        for a,b,c in re.findall(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>",blk):
            a,b,c=int(a,16),int(b,16),int(c,16)
            for i in range(a,b+1): cm.setdefault(i,chr(c+i-a))
out=[]
for s in streams:
    if b"BT" not in s or b"Tj" not in s: continue
    lasty=None
    for t in re.finditer(rb"1 0 0 -1 ([\d.\-]+) ([\d.\-]+) Tm|<([0-9A-Fa-f]+)>\s*Tj|ActualText",s):
        if t.group(2):
            y=t.group(2)
            if y!=lasty: out.append("\n"); lasty=y
        elif t.group(3):
            h=t.group(3).decode()
            for i in range(0,len(h),4): out.append(cm.get(int(h[i:i+4],16),"?"))
    out.append("\n=====PAGE=====\n")
print("".join(out))
'

