  if (error instanceof ApiError && (error.isClientError || error.kind === 'invalid_response')) {
    return false;
  }
  return failureCount < 1;
}

export const queryClient = new QueryClient({
  defaultOptions: { queries: { retry: shouldRetry } },
});
