  1	import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
  2	import { App } from 'antd';
  3	import { useCallback, useEffect, useReducer } from 'react';
  4	
  5	import { ApiError } from '../../api/client';
  6	import { createJob, deleteJob, listJobs, updateJobStatus } from '../../api/jobs';
  7	import type { Job, JobStatusType } from '../../types/job';
  8	import { failureText, isJobGone } from './errorCopy';
  9	import type { MutationFailure } from './errorCopy';
 10	import { STATUS_META } from './statusMeta';
 11	
 12	const jobsKeys = {
 13	  /** Prefix of every cached page; invalidating it marks them all stale. */
 14	  all: ['jobs'] as const,
 15	  page: (cursor: string | null) => ['jobs', cursor] as const,
 16	};
 17	
 18	const ERROR_TOAST_SECONDS = 5;
 19	
 20	// TODO: the position lives in memory only, so a reload returns to the first
 21	//  page. Deferred: no router in this app and the brief asks for one page. Fix:
 22	//  keep `cursor` in the URL query string and read it back on load.
 23	/** Where the list is: the cursor the API understands, and a page number only the client knows. */
 24	type Position = Readonly<{ cursor: string | null; pageIndex: number }>;
 25	
 26	type Move =
 27	  | Readonly<{ type: 'first' }>
 28	  | Readonly<{ type: 'next'; cursor: string }>
 29	  | Readonly<{ type: 'previous'; cursor: string }>;
 30	
 31	const FIRST_PAGE: Position = { cursor: null, pageIndex: 0 };
 32	
 33	function move(position: Position, action: Move): Position {
 34	  switch (action.type) {
 35	    case 'first':
 36	      // Same object when already there, so React skips the re-render.
 37	      return position.cursor === null ? position : FIRST_PAGE;
 38	    case 'next':
 39	      return { cursor: action.cursor, pageIndex: position.pageIndex + 1 };
 40	    case 'previous':
 41	      return { cursor: action.cursor, pageIndex: Math.max(0, position.pageIndex - 1) };
 42	  }
 43	}
 44	
 45	export type JobsPageState = Readonly<{
 46	  jobs: readonly Job[];
 47	  /**
 48	   * Zero-based number of the page on screen. The API never counts rows, so
 49	   * this is the client's own tally of Next and Previous clicks; it drifts if
 50	   * other users add or delete jobs while this one pages.
 51	   */
 52	  pageIndex: number;
 53	  /** A page is being fetched for the first time; `jobs` is empty or still the previous page. */
 54	  isLoadingPage: boolean;
 55	  /** The last fetch failed. `jobs` may still hold the rows from before it. */
 56	  error: Error | null;
 57	  hasNext: boolean;
 58	  hasPrevious: boolean;
 59	  goNext: () => void;
 60	  goPrevious: () => void;
 61	  goFirst: () => void;
 62	  retry: () => void;
 63	}>;
 64	
 65	/**
 66	 * The page of jobs on screen and the controls that move it.
 67	 *
 68	 * Each page is cached under its cursor. While the next one loads, the previous
 69	 * rows stay on screen (`isLoadingPage` is true) instead of the table emptying.
 70	 */
 71	export function useJobsPage(): JobsPageState {
 72	  const [position, dispatch] = useReducer(move, FIRST_PAGE);
 73	  const query = useQuery({
 74	    queryKey: jobsKeys.page(position.cursor),
 75	    queryFn: ({ signal }) => listJobs(position.cursor, signal),
 76	    placeholderData: keepPreviousData,
 77	  });
 78	
 79	  const showsOwnData = query.data !== undefined && !query.isPlaceholderData;
 80	  // While the next page loads these still describe the page on screen, so the
 81	  // pager keeps its shape; its buttons are disabled until the load ends.
 82	  const next = query.data?.next ?? null;
 83	  const previous = query.data?.previous ?? null;
 84	
 85	  // A later page can stop being usable: its cursor went stale (the API answers
 86	  // 404), or its last job was deleted. Both end on the first page.
 87	  const isPageUnusable =
 88	    position.cursor !== null &&
 89	    ((query.error !== null && isJobGone(query.error)) || (showsOwnData && query.data.results.length === 0));
 90	  useEffect(() => {
 91	    if (isPageUnusable) {
 92	      dispatch({ type: 'first' });
 93	    }
 94	  }, [isPageUnusable]);
 95	
 96	  const { refetch } = query;
 97	  const goNext = useCallback(() => {
 98	    if (next !== null) {
 99	      dispatch({ type: 'next', cursor: next });
100	    }
101	  }, [next]);
102	  const goPrevious = useCallback(() => {
103	    if (previous !== null) {
104	      dispatch({ type: 'previous', cursor: previous });
105	    }
106	  }, [previous]);
107	  const goFirst = useCallback(() => dispatch({ type: 'first' }), []);
108	  const retry = useCallback(() => void refetch(), [refetch]);
109	
110	  return {
111	    jobs: query.data?.results ?? NO_JOBS,
112	    pageIndex: position.pageIndex,
113	    isLoadingPage: query.isPending || query.isPlaceholderData,
114	    error: isPageUnusable ? null : query.error,
115	    hasNext: next !== null,
116	    hasPrevious: previous !== null,
117	    goNext,
118	    goPrevious,
119	    goFirst,
120	    retry,
121	  };
122	}
123	
124	// One shared empty array, so "no data yet" does not look like new data on every render.
125	const NO_JOBS: readonly Job[] = [];
126	
127	// The three mutations below report their own result as a toast, here and not
128	// in the component that started them: a deleted job's row is unmounted by the
129	// time its request settles, and a callback passed to `mutate()` from that row
130	// would never run.
131	//
132	// Each `onSuccess` returns the refetch promise, which keeps `isPending` true
133	// until the new list is on screen. The control stays disabled for that whole
134	// time, and what the row shows is always what the server stored.
135	
136	/**
137	 * @returns A callback that shows the failure toast, and reloads the list when
138	 *   the job turned out to be gone.
139	 */
140	function useReportFailure(failure: MutationFailure): (error: Error) => Promise<void> {
141	  const queryClient = useQueryClient();
142	  const { message } = App.useApp();
143	  return useCallback(
144	    async (error: Error) => {
145	      void message.error(failureText(failure, error), ERROR_TOAST_SECONDS);
146	      if (isJobGone(error)) {
147	        await queryClient.invalidateQueries({ queryKey: jobsKeys.all });
148	      }
149	    },
150	    [failure, message, queryClient],
151	  );
152	}
153	
154	/**
155	 * Create a job, then show the first page, where the new job is the top row.
156	 *
157	 * A refusal of the name itself (blank, too long, duplicate) is not reported
158	 * here: the form shows it under the input.
159	 *
160	 * @param onCreated Moves the list to its first page.
161	 */
162	export function useCreateJob(onCreated: () => void) {
163	  const queryClient = useQueryClient();
164	  const { message } = App.useApp();
165	  return useMutation({
166	    mutationFn: createJob,
167	    onSuccess: async () => {
168	      // Mark every page stale without refetching the one being left, then
169	      // load the first page. If it is not cached, mounting it fetches it.
170	      await queryClient.invalidateQueries({ queryKey: jobsKeys.all, refetchType: 'none' });
171	      onCreated();
172	      await queryClient.refetchQueries({ queryKey: jobsKeys.page(null), exact: true });
173	      void message.success('Job created');
174	    },
175	    onError: (error) => {
176	      if (nameErrorCodeOf(error) === null) {
177	        void message.error(failureText('createFailed', error), ERROR_TOAST_SECONDS);
178	      }
179	    },
180	  });
181	}
182	
183	/**
184	 * @returns The API's error code for the name field, or `null` if the failure is not about the name.
185	 */
186	export function nameErrorCodeOf(error: Error): string | null {
187	  return error instanceof ApiError ? error.fieldCode('name') : null;
188	}
189	
190	/** Set one job's status. The server appends an entry to the job's status log on every call. */
191	export function useChangeStatus(jobId: number) {
192	  const queryClient = useQueryClient();
193	  const { message } = App.useApp();
194	  return useMutation({
195	    mutationFn: (status: JobStatusType) => updateJobStatus(jobId, status),
196	    onSuccess: async (job) => {
197	      await queryClient.invalidateQueries({ queryKey: jobsKeys.all });
198	      void message.success(`Status set to ${STATUS_META[job.current_status].label}`);
199	    },
200	    onError: useReportFailure('updateFailed'),
201	  });
202	}
203	
204	/** Delete one job and its status log. */
205	export function useDeleteJob(jobId: number) {
206	  const queryClient = useQueryClient();
207	  const { message } = App.useApp();
208	  return useMutation({
209	    mutationFn: () => deleteJob(jobId),
210	    onSuccess: async () => {
211	      await queryClient.invalidateQueries({ queryKey: jobsKeys.all });
212	      void message.success('Job deleted');
213	    },
214	    onError: useReportFailure('deleteFailed'),
215	  });
216	}
  1	import { Card, Typography } from 'antd';
  2	
  3	import { PAGE_SIZE } from '../../api/jobs';
  4	import { CreateJobForm } from './CreateJobForm';
  5	import { CursorPager } from './CursorPager';
  6	import { useJobsPage } from './hooks';
  7	import { JobsTable, LoadErrorAlert } from './JobsTable';
  8	
  9	const NO_PADDING = { body: { padding: 0 } } as const;
 10	// 30px as designed; smaller on a phone, where three lines of title would push the form down.
 11	const TITLE_STYLE = { margin: 0, fontSize: 'clamp(22px, 6vw, 30px)' } as const;
 12	
 13	type RangeText = Readonly<{ short: string; long: string }>;
 14	
 15	/**
 16	 * Which rows are on screen, e.g. "21–40". The total appears only on the last
 17	 * page, the one place a cursor API reveals it: there is no `COUNT(*)`.
 18	 *
 19	 * @param pageIndex Zero-based page number, as the client counted it.
 20	 * @param rowCount Rows on this page; at least 1.
 21	 * @param hasNext Whether a later page exists.
 22	 */
 23	function rangeText(pageIndex: number, rowCount: number, hasNext: boolean): RangeText {
 24	  const from = pageIndex * PAGE_SIZE + 1;
 25	  const to = from + rowCount - 1;
 26	  const span = from === to ? String(from) : `${from}–${to}`;
 27	  if (hasNext) {
 28	    return { short: span, long: `Showing ${span}` };
 29	  }
 30	  return {
 31	    short: `${span} of ${to}`,
 32	    long: pageIndex === 0 ? `${to} ${to === 1 ? 'job' : 'jobs'}` : `Showing ${span} of ${to}`,
 33	  };
 34	}
 35	
 36	/** The whole application: create a job, see the list, change a status, delete. */
 37	export function JobsPage() {
 38	  const page = useJobsPage();
 39	  const { jobs, isLoadingPage, error } = page;
 40	
 41	  const hasRows = jobs.length > 0;
 42	  const hasPager = page.hasPrevious || page.hasNext;
 43	  // No range while a page loads: the rows on screen are still the last page's.
 44	  const range = hasRows && !isLoadingPage ? rangeText(page.pageIndex, jobs.length, page.hasNext) : null;
 45	
 46	  const pager = (label: string) => (
 47	    <CursorPager
 48	      label={label}
 49	      hasPrevious={page.hasPrevious}
 50	      hasNext={page.hasNext}
 51	      disabled={isLoadingPage}
 52	      onPrevious={page.goPrevious}
 53	      onNext={page.goNext}
 54	    />
 55	  );
 56	
 57	  return (
 58	    <main className="jobs-page">
 59	      <header className="jobs-page__header">
 60	        <div className="jobs-page__logo" aria-hidden="true">
 61	          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
 62	            <path d="M12 3l9 4.5-9 4.5-9-4.5L12 3z" />
 63	            <path d="M3 12l9 4.5 9-4.5" />
 64	            <path d="M3 16.5L12 21l9-4.5" opacity="0.7" />
 65	          </svg>
 66	        </div>
 67	        <div>
 68	          <Typography.Title level={1} style={TITLE_STYLE}>
 69	            Job Management Dashboard
 70	          </Typography.Title>
 71	          <Typography.Text type="secondary">Create computational jobs and keep their status up to date.</Typography.Text>
 72	        </div>
 73	      </header>
 74	
 75	      <Card styles={NO_PADDING}>
 76	        <div className="jobs-page__toolbar">
 77	          <CreateJobForm onCreated={page.goFirst} />
 78	          {hasPager && (
 79	            <div className="jobs-page__range">
 80	              {range?.short}
 81	              {pager('Pagination, top')}
 82	            </div>
 83	          )}
 84	        </div>
 85	
 86	        {/* A refresh failed but the last rows are still here: keep them, and say so. */}
 87	        {error !== null && hasRows && <LoadErrorAlert className="jobs-page__alert" onRetry={page.retry} />}
 88	
 89	        <JobsTable jobs={jobs} loading={isLoadingPage} failed={error !== null} onRetry={page.retry} />
 90	
 91	        {(hasRows || hasPager) && (
 92	          <div className="jobs-page__footer">
 93	            <div className="jobs-page__range" aria-live="polite">
 94	              {range?.long}
 95	            </div>
 96	            {hasPager && pager('Pagination, bottom')}
 97	          </div>
 98	        )}
 99	      </Card>
100	    </main>
101	  );
102	}
