  2	import type { FormRule } from 'antd';
  3	import { memo } from 'react';
  4	
  5	import { nameErrorText } from './errorCopy';
  6	import { nameErrorCodeOf, useCreateJob } from './hooks';
  7	
  8	/** Same limit as the `name` column (backend `Job.name`, `max_length=255`). */
  9	const NAME_MAX_LENGTH = 255;
 10	
 11	type FormValues = Readonly<{ name?: string }>;
 12	
 13	/**
 14	 * Check a name the way the server will, and answer with the server's own
 15	 * error code so both sources share one line of text each.
 16	 *
 17	 * Length is counted in code points (`[...text]`), as Django counts it;
 18	 * `text.length` counts UTF-16 units and would refuse 200 emoji that the
 19	 * server accepts.
 20	 */
 21	function nameErrorCode(value: unknown): 'blank' | 'max_length' | null {
 22	  const name = typeof value === 'string' ? value.trim() : '';
 23	  if (name === '') {
 24	    return 'blank';
 25	  }
 26	  return [...name].length > NAME_MAX_LENGTH ? 'max_length' : null;
 27	}
 28	
 29	const NAME_RULES: FormRule[] = [
 30	  {
 31	    validator: (_rule, value: unknown) => {
 32	      const code = nameErrorCode(value);
 33	      return code === null ? Promise.resolve() : Promise.reject(new Error(nameErrorText(code)));
 34	    },
 35	  },
 36	];
 37	
 38	export type CreateJobFormProps = Readonly<{
 39	  /** Called once the job exists; moves the list to its first page. */
 40	  onCreated: () => void;
 41	}>;
 42	
 43	/**
 44	 * One-line form that creates a job.
 45	 *
 46	 * The input's state lives in the form, so typing re-renders this component
 47	 * only, never the table next to it.
 48	 */
 49	export const CreateJobForm = memo(function CreateJobForm({ onCreated }: CreateJobFormProps) {
 50	  const [form] = Form.useForm<FormValues>();
 51	  const { mutate: createJob, isPending } = useCreateJob(onCreated);
 52	
 53	  const onFinish = (values: FormValues) => {
 54	    // Enter can submit again while the first request is still out.
 55	    if (isPending) {
 56	      return;
 57	    }
 58	    createJob((values.name ?? '').trim(), {
 59	      // Not resetFields(): that remounts the input and drops the keyboard focus,
 60	      // and the next job name is most likely typed straight away.
 61	      onSuccess: () => form.setFieldsValue({ name: '' }),
 62	      onError: (error) => {
 63	        // The server is the authority: it also refuses a name another job has.
 64	        const code = nameErrorCodeOf(error);
 65	        if (code !== null) {
 66	          form.setFields([{ name: 'name', errors: [nameErrorText(code)] }]);
 67	        }
 68	      },
 69	    });
 70	  };
 71	
 72	  // Validation runs on submit only, so an error from the last attempt would
 73	  // otherwise stay under the input while the user is already correcting it.
 74	  const clearNameError = () => {
 75	    if (form.getFieldError('name').length > 0) {
 76	      form.setFields([{ name: 'name', errors: [] }]);
 77	    }
 78	  };
 79	
 80	  // TODO: the error text is tied to the input (aria-describedby, aria-invalid)
 81	  //  but is not a live region, so a screen reader reads it on focus, not the
 82	  //  moment it appears. Deferred: AntD renders the help text itself. Fix: pass
 83	  //  `help` as an element with role="alert".
 84	  return (
 85	    <Form form={form} className="create-job-form" onFinish={onFinish} onValuesChange={clearNameError}>
 86	      <Form.Item name="name" className="create-job-form__name" rules={NAME_RULES} validateTrigger="onSubmit">
 87	        <Input aria-label="Job name" placeholder="New job name, e.g. Fluid Dynamics Simulation" autoComplete="off" />
 88	      </Form.Item>
 89	      <Button type="primary" htmlType="submit" loading={isPending}>
 90	        Create job
 91	      </Button>
 92	    </Form>
 93	  );
 94	});
  1	/** Why a request failed: no response at all, an error status, or a 2xx body that is not what the API promises. */
  2	export type ApiErrorKind = 'network' | 'http' | 'invalid_response';
  3	
  4	type ApiErrorDetails = Readonly<{
  5	  /** HTTP status; absent for `network`. */
  6	  status?: number;
  7	  /** Error codes per request field, e.g. `{ name: ['duplicate'] }`. */
  8	  fieldCodes?: Readonly<Record<string, readonly string[]>>;
  9	  /** Code of an error about the request as a whole, e.g. `not_found`. */
 10	  detailCode?: string;
 11	}>;
 12	
 13	/**
 14	 * The one error type every API call rejects with. It carries the API's stable
 15	 * error codes and never its English messages: display text is chosen by code
 16	 * (see features/jobs/errorCopy.ts).
 17	 */
 18	export class ApiError extends Error {
 19	  readonly kind: ApiErrorKind;
 20	  readonly status: number | null;
 21	  readonly fieldCodes: Readonly<Record<string, readonly string[]>>;
 22	  readonly detailCode: string | null;
 23	
 24	  constructor(kind: ApiErrorKind, details: ApiErrorDetails = {}) {
 25	    super(details.status === undefined ? `API request failed (${kind})` : `API request failed (${kind}, ${details.status})`);
 26	    this.name = 'ApiError';
 27	    this.kind = kind;
 28	    this.status = details.status ?? null;
 29	    this.fieldCodes = details.fieldCodes ?? {};
 30	    this.detailCode = details.detailCode ?? null;
 31	  }
 32	
 33	  /**
 34	   * @returns The first error code the API gave for a request field, or `null`.
 35	   */
 36	  fieldCode(field: string): string | null {
 37	    return this.fieldCodes[field]?.[0] ?? null;
 38	  }
 39	}
 40	
 41	export function isRecord(value: unknown): value is Record<string, unknown> {
 42	  return typeof value === 'object' && value !== null && !Array.isArray(value);
 43	}
 44	
 45	const REQUEST_TIMEOUT_MS = 15_000;
 46	
 47	type RequestOptions = Readonly<{
 48	  method?: 'GET' | 'POST' | 'PATCH' | 'DELETE';
 49	  /** Sent as JSON. The API answers 415 to any other content type. */
 50	  body?: Readonly<Record<string, unknown>>;
 51	  signal?: AbortSignal;
 52	}>;
 53	
 54	/**
 55	 * Call the API and return the parsed JSON body, or `undefined` for a 204.
 56	 *
 57	 * The result is `unknown` on purpose: callers pass it through a decoder
 58	 * (api/decode.ts) instead of asserting a type the network never promised.
 59	 *
 60	 * @param path Relative URL, so the same build works behind any host or port.
 61	 * @throws ApiError for a network failure, a timeout or a non-2xx status. An aborted
 62	 *   request rejects with the browser's own `AbortError`.
 63	 */
 64	export async function request(path: string, options: RequestOptions = {}): Promise<unknown> {
 65	  const { method = 'GET', body, signal } = options;
 66	  const init: RequestInit = { method, headers: { Accept: 'application/json' } };
 67	  if (body !== undefined) {
 68	    init.headers = { ...init.headers, 'Content-Type': 'application/json' };
 69	    init.body = JSON.stringify(body);
 70	  }
 71	  // Give up after a while: a request that never answers would otherwise leave
 72	  // its spinner (or its disabled button) on screen for good.
 73	  const timeout = AbortSignal.timeout(REQUEST_TIMEOUT_MS);
 74	  init.signal = signal === undefined ? timeout : AbortSignal.any([signal, timeout]);
 75	
 76	  let response: Response;
 77	  try {
 78	    response = await fetch(path, init);
 79	  } catch (cause) {
 80	    // Cancelled by the caller (the page it was for is gone): not a failure to report.
 81	    if (signal?.aborted) {
 82	      throw cause;
 83	    }
 84	    throw new ApiError('network');
 85	  }
 86	
 87	  if (!response.ok) {
 88	    throw new ApiError('http', { status: response.status, ...(await readErrorCodes(response)) });
 89	  }
 90	  if (response.status === 204) {
