100	/**
101	 * Pull the codes out of an error body. The API sends
102	 * `{"name": [{"message", "code"}]}` for a field and
103	 * `{"detail": {"message", "code"}}` for the request; nginx (502) and Django's
104	 * own error pages send HTML, which yields no codes.
105	 */
106	async function readErrorCodes(response: Response): Promise<ApiErrorDetails> {
107	  let body: unknown;
108	  try {
109	    body = await response.json();
110	  } catch {
111	    return {};
112	  }
113	  if (!isRecord(body)) {
114	    return {};
115	  }
