117	  const fieldCodes: Record<string, readonly string[]> = {};
118	  let detailCode: string | undefined;
119	  for (const [key, value] of Object.entries(body)) {
120	    if (Array.isArray(value)) {
121	      const codes = value.map(readCode).filter((code) => code !== undefined);
122	      if (codes.length > 0) {
123	        fieldCodes[key] = codes;
124	      }
125	    } else if (key === 'detail') {
126	      detailCode = readCode(value);
127	    }
128	  }
129	  return detailCode === undefined ? { fieldCodes } : { fieldCodes, detailCode };
130	}
131	
132	function readCode(item: unknown): string | undefined {
133	  return isRecord(item) && typeof item.code === 'string' ? item.code : undefined;
134	}

