 47	type RequestOptions = Readonly<{
 48	  method?: 'GET' | 'POST' | 'PATCH' | 'DELETE';
 49	  /** Sent as JSON. The API answers 415 to any other content type. */
 50	  body?: Readonly<Record<string, unknown>>;
 51	  signal?: AbortSignal;
 52	}>;
