 69	    init.body = JSON.stringify(body);
 70	  }
 71	  // Give up after a while: a request that never answers would otherwise leave
 72	  // its spinner (or its disabled button) on screen for good.
 73	  const timeout = AbortSignal.timeout(REQUEST_TIMEOUT_MS);
 74	  init.signal = signal === undefined ? timeout : AbortSignal.any([signal, timeout]);
 75	
