 83	    }
 84	    throw new ApiError('network');
 85	  }
 86	
 87	  if (!response.ok) {
 88	    throw new ApiError('http', { status: response.status, ...(await readErrorCodes(response)) });
 89	  }
 90	  if (response.status === 204) {
 91	    return undefined;
 92	  }
